-- =============================================================================
-- Eden Apothecary: pre-1900 energetics sources for 25 more herbs (research
-- batch 3). DATA ONLY. Written 2026-09-15.
-- =============================================================================
-- Founder approvals, 2026-09-15:
--   * Batch 3 approved as researched. It changes NO app value: every stored
--     temperature and moisture in this batch was judged clear, so the July 2026
--     ruling keeps all of them. This migration writes evidence and nothing else.
--   * Four counting questions raised by batch 3 were answered, each confirming
--     the default batch 3 had already applied, so no herb needed rebuilding:
--       1. A drug several species make (aloes, myrrh, camphor, benzoin, catechu):
--          SHOW the old reading, COUNT it for no herb, because the old writer
--          described a different plant. Cape aloes (Aloe ferox, named 1768) and
--          German chamomile therefore end with no counted source.
--       2. Species mismatch generally (Roman vs German chamomile): same rule.
--       3. An authority named at the END of an entry (Culpeper's trailing
--          'Galen.') IS counted as his own reading; an inline 'as Galen saith'
--          is second-hand and is not.
--       4. One book giving two readings by preparation (Bhavaprakasha: dried
--          ginger snigdha, fresh ginger ruksha): count the preparation the app
--          describes (dried), show the other.
--
-- WHAT THIS MIGRATION DOES
--   Writes public.herbs.energetics_citation for 25 herbs that had NULL
--   (5 where the old sources agree, 10 where they disagree and the page will say
--   so, 6 with no pre-1900 source found). Same jsonb object shape as batches 1
--   and 2, carrying 'batch': 3. The 69 legacy single-source citations are NOT
--   touched, and neither are the 50 herbs already carrying a batch object.
--
--
--   It also carries a SECOND founder decision from 2026-09-15, which corrects
--   something already live. A herb where old readings WERE found but none of them
--   counted (wrong species, wrong plant part, or the writer was quoting someone
--   else) rendered NOTHING to a free reader, which reads as 'nobody looked'. Such
--   a herb now carries its own plain sentence saying why, e.g. Cape Aloes:
--     'No pre-1900 source found for this exact plant. The old books describe aloes from other species, not the South African plant this entry is about.'
--   7 herbs are in that position: H299, H007, H014, H020 new in batch 3, and H164, H190, H286 already live from
--   batches 1 and 2, which section 2 backfills. The line is FREE, like the
--   disagreement sentence, because honesty about the evidence is not a paid
--   feature. It is NOT the same as 'no_pre1900_source_found', which stays reserved
--   for a search that turned up nothing at all.
--
--   public.herb_energetics_evidence_v (20260916190000) is replaced to append that
--   one new free column. Every column above it, including the Root gate, is
--   unchanged. It selects every herb carrying a batch object, so these 25 herbs
--   appear in it automatically once their citation is written.
--
-- BLAST RADIUS: production data on 28 of 300 herbs in public.herbs (a citation
-- where it is currently NULL), plus one added key on 3 herbs already carrying a
-- citation, plus one added column on an existing client-readable view. No
-- temperature or moisture value changes; section 4 asserts that none moved. No
-- other schema change, no grant change, no RLS change.
--
-- IDEMPOTENT. Verification DO blocks at the bottom abort the whole transaction if
-- any assertion fails.
-- =============================================================================

begin;

-- -----------------------------------------------------------------------------
-- 0. Snapshot: every herb's energetics before this migration. Section 4 asserts
--    that NOTHING moved, because batch 3 changes no app value.
-- -----------------------------------------------------------------------------
create temporary table _energetics_before_b3 on commit drop as
  select herb_id, temperature, moisture from public.herbs;

-- -----------------------------------------------------------------------------
-- 1. The researched sources, one INSERT per herb into a staging table, applied
--    under a single guard loop. The guard refuses to overwrite anything that is
--    not NULL and not already a batch object.
-- -----------------------------------------------------------------------------
create temporary table _energetics_batch3 (
  herb_id text primary key,
  citation jsonb not null
) on commit drop;

-- H299 Cape Aloes (Bitter Aloes) (3 sources, single reading)
insert into _energetics_batch3 values ('H299', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 3, "checked_no_reading": ["Dymock, Pharmacographia Indica Vol. III (1893), LILIACEAE: monographs for Aloe perryi, Aloe abyssinica and Aloe vera only; no entry and no thermal quality for Aloe ferox", "Searched every downloaded text for 'Cape aloes' and 'Aloe ferox': no pre-1900 hit anywhere (Dymock, Watt Vol. IV, Salmon, Porter Smith)", "Salmon, Botanologia (1710): no chapter for the drug aloes (the book covers English herbs)", "Culpeper 1653, 'Aloes' among the gums and juices: purging virtues only, no degree"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The old books describe aloes from other species, not the South African plant this entry is about.", "no_pre1900_source_found": false, "notes": ["This is the herb deferred from batch 2. It is the clearest case yet of a drug that the old books describe by the article of trade rather than by the species, so the answer depends on a rule you have not been asked for yet (question 1 below).", "The stored part is the dried bitter leaf juice, the article of commerce called Cape aloes. Aloe ferox was not separated from the other aloes until Miller named it in 1768, so every pre-1900 reading below is for the drug aloes of an earlier, different species."], "part_used": "Dried leaf-juice concentrate, the bitter yellow latex tapped from the cut leaf and evaporated to a hard lump ('drug aloes' / Cape aloes). This is the anthranoid latex, distinct from the clear inner-leaf gel.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Gerard's herb aloe is the Mediterranean and Indian plant, not the South African Aloe ferox. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Aloe, that is to say, the juice which is used in physic, is good for many things. It is hot, and that in the first or second degree, but dry in the third, extreme bitter, yet without biting.", "gloss": "The drug aloes is hot in the first or second degree and dry in the third.", "locator": "Book III, Chap. 141 'Of Herb Aloe or Sea Houseleek', The Temperature", "not_counted_why": "Gerard's herb aloe is the Mediterranean and Indian plant, not the South African Aloe ferox. Shown, not counted.", "note": "Gerard's herb aloe is the Mediterranean and Indian plant, not the South African Aloe ferox. Shown, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. The Chinese drug came by Arab trade from the Socotrine and common aloes, not from Aloe ferox. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味苦寒無毒主治熱風煩悶胸膈間熱氣明目鎮心小兒癲癎驚風", "gloss": "Aloes (lu hui): bitter, cold, not toxic. For hot wind, vexation, heat in the chest and diaphragm.", "locator": "卷三十四 木之一, 盧㑹 (蘆薈), 氣味 (heading credited to 開寶, 973)", "not_counted_why": "The Chinese drug came by Arab trade from the Socotrine and common aloes, not from Aloe ferox. Shown, not counted.", "note": "The Chinese drug came by Arab trade from the Socotrine and common aloes, not from Aloe ferox. Shown, not counted.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. Indian kumārī is Aloe vera (Aloe indica of the old books), a different species. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "कुमारी गृहकन्या च कन्या घृतकुमारिका । कुमारी भेदनी शीता तिक्ता नेत्र्या रसायनी ॥", "gloss": "kumārī bhedanī śītā tiktā netryā rasāyanī: aloe is purging, COLD, bitter, good for the eyes, a rasayana.", "locator": "Guḍūcyādi varga 4.229", "not_counted_why": "Indian kumārī is Aloe vera (Aloe indica of the old books), a different species. Shown, not counted.", "note": "Indian kumārī is Aloe vera (Aloe indica of the old books), a different species. Shown, not counted.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H002 Astragalus (2 sources, sources agree)
insert into _energetics_batch3 values ('H002', $j${"agreement_state": "agree", "app_value": {"moisture": "Neutral", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (stored value unclear; no pre-1900 source found, so nothing to replace it)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 3, "checked_no_reading": ["Bencao Congxin (1757): the Wikisource text carries no huang qi entry", "Porter Smith 1871: no Astragalus article", "Gerard 1633 Book II Chap. 520 'Of Milk Vetch' is a European Astragalus, and says only that it is drying, 'as Galen saith'"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Warm", "source": "Shennong Bencao Jing (c. 200 CE)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": [], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value unclear (the stored moisture is Neutral but the energetics summary in the same record reads 'Warm and neutral-moist', hedging between two values); no first-hand pre-1900 source found, so the stored value stays for now.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "==黃==味甘，微溫。主癰疽久敗創，排膿止痛，大風痢疾，五痔鼠，補虛，小兒百病。一名戴糝。生山谷。", "gloss": "Astragalus (huang qi): sweet, slightly WARM. For abscesses and long-festering sores, draws pus and stops pain, for great wind, piles, and all the diseases of children.", "locator": "上經 (upper class), 黃耆; the character 耆 has dropped out of this Wikisource transcription, but the alternative names 戴糝, 戴椹, 獨椹, 蜀脂, 百本 and the indications identify the entry", "not_counted_why": "", "note": "", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. The heading repeats the Shennong reading word for word and credits it, so it counts once, credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "根氣味甘微温無毒{{SKnotes|本經}}白水者冷補", "gloss": "Root: sweet, slightly warm, not toxic (credited to the Shennong Bencao Jing). The kind from Baishui is cooling and supplementing.", "locator": "卷十二上 草之一, 黃耆, 根 氣味", "not_counted_why": "The heading repeats the Shennong reading word for word and credits it, so it counts once, credited to Shennong.", "note": "The heading repeats the Shennong reading word for word and credits it, so it counts once, credited to Shennong.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Neutral", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "unclear", "why": "the stored moisture is Neutral but the energetics summary in the same record reads 'Warm and neutral-moist', hedging between two values"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H003 Burdock (5 sources, SOURCES DISAGREE)
insert into _energetics_batch3 values ('H003', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources disagree, shown on page)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 3, "checked_no_reading": ["Salmon, Botanologia (1710), Chap. C 'Of Burdock Small': a different species (Xanthium), temperate as to heat and cold", "Culpeper's herbal chapter 'Burdock': 'Venus challengeth this herb', no degree"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Cool", "source": "Culpeper (1653)"}, {"reading": "Cool", "source": "Salmon (1710)"}, {"reading": "Neutral", "source": "Bencao Gangmu (1596)"}, {"reading": "Cool", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "On temperature, the old sources disagree: Gerard (1633) reads it as warm; Culpeper (1653), Salmon (1710) and Bencao Congxin (1757) read it as cool or cold; Bencao Gangmu (1596) reads it as neutral. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it. On moisture, Gerard (1633), Culpeper (1653) and Salmon (1710) read it as dry. The app keeps moist, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are root, seed and leaf, so readings for any of the three are counted."], "part_used": "Root, Seed, Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The leaves of Clot-Bur are of temperature moderately dry and wasting; the root is something hot. The seed of the lesser Bur, as Galen saith, hath power to digest, therefore it is hot and dry.", "gloss": "The leaves are moderately drying; the root is somewhat hot.", "locator": "Book II, Chap. 290 'Of Clot-Bur, or Burdock', The Temperature", "not_counted_why": "", "note": "The root gives the temperature and the leaf the moisture. The sentence about the seed is Gerard reporting Galen, so it is not used.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Bardana. Clot-bur, or Bur-dock: temperately dry and wasting, something cooling; it is held to be good against the shrinking of the sinews", "gloss": "Burdock is moderately drying and somewhat cooling.", "locator": "Catalogue of simples, Herbs, 'Bardana' (Gutenberg #49513, offset ~847460)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The Qualities. They are all cooling and drying in the firſt Degree ; yet Gerard ſays, that the Roots are moderately hot", "gloss": "Burdock is cooling and drying in the first degree; Salmon notes that Gerard called the root moderately hot.", "locator": "Chap. XCVIII 'Of Burdock Great', The Qualities (OCR line near offset 836261)", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Counted: differs from the app temperature (source neutral, app cool).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "氣味辛平無毒}}{{SKnotes|藏器曰苦元素曰辛温陽中之隂升也杲曰辛平陽也降也}}主治明目補中除風傷", "gloss": "Burdock seed (e shi, niu bang zi): pungent, NEUTRAL, not toxic. Brightens the eyes, supplements the centre, dispels wind injury.", "locator": "卷十五 草之四, 惡實 (牛蒡子), 氣味", "not_counted_why": "", "note": "", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "卷三草部惡實一名牛蒡子、一名鼠粘子。瀉熱解毒。辛苦而寒。瀉熱散结除風。… 根苦寒。", "gloss": "Burdock seed: drains heat and resolves toxin; pungent, bitter and COLD. The root is bitter and cold.", "locator": "卷三 草部, 惡實", "not_counted_why": "", "note": "", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

