insert into _energetics_batch3 values ('H004', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources disagree, shown on page)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 3, "checked_no_reading": ["Culpeper's herbal chapter 'Marigolds': 'an herb of the Sun, and under Leo', no degree", "Gerard Book II Chaps. 256, 257 and 259 are German, Corn, French and Peruvian marigolds, other plants entirely"], "counted_readings": {"moisture": [{"reading": "Neutral", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it. On moisture, Salmon (1710) reads it as neutral. The app keeps moist, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the flower, so the readings counted below are the ones given for the flower."], "part_used": "Flower", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "The flower of the Marigold is of temperature hot, almost in the second degree, especially when it is dry … But the leaves of the herb are hotter", "gloss": "The marigold flower is hot, almost in the second degree; the leaves are hotter still.", "locator": "Book II, Chap. 255 'Of Marigolds', The Temperature and Virtues", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Culpeper gives the degree for the LEAVES; the stored part is the flower. Shown, not counted.", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Calendula, &c. Marigolds. The leaves are hot in the second degree, and something moist, loosen the belly", "gloss": "The leaves are hot in the second degree and somewhat moist.", "locator": "Catalogue of simples, Herbs, 'Calendula' (Gutenberg #49513, offset ~852756)", "not_counted_why": "Culpeper gives the degree for the LEAVES; the stored part is the flower. Shown, not counted.", "note": "Culpeper gives the degree for the LEAVES; the stored part is the flower. Shown, not counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); differs from the app moisture (source neutral, app moist).", "assigns_moisture": "Neutral", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The Qualities. The Flowers are hot in the firſt Degree, and temperate in reſpect of dryneſs or moiſture. The Herb is hot almoſt in the ſecond Degree, and moiſt in the firſt.", "gloss": "The flowers are hot in the first degree and temperate as to dryness or moisture; the herb is hotter and moist in the first degree.", "locator": "Chap. CCCCLXX 'Of Marigold Garden', The Qualities (OCR near offset 3754544)", "not_counted_why": "", "note": "Galenic 'temperate in respect of dryness or moisture' counts as a Neutral moisture.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

