 "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "In the fourth degree. Pepper, white, black and long, Guinny Pepper.", "gloss": "Culpeper's table of fruits puts Guinea pepper (capsicum) hot in the fourth degree. His drying table says only 'All sorts of pepper', a group.", "locator": "Catalogue of simples, Fruits, the degree tables (Gutenberg #49513, offset ~970100)", "not_counted_why": "", "note": "The heat entry names Guinea Pepper, so it counts. The drying entry says 'All sorts of pepper', a group statement, so the moisture is shown but not counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Hot"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Hot"}}}$j$::jsonb);

