insert into _energetics_batch3 values ('H007', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 3, "checked_no_reading": ["Culpeper's degree tables list a bare 'Chamomel' under hot in the first degree and dry in the first degree, a plain plant name in a list, so it is context rather than a species reading", "Gerard Book II Chap. 263 'Of Mayweed, or Wild Camomile': 'the faculties are unknown; yet all of them are thought to be hot and dry', a guess about another plant"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The old books give their degree for Roman chamomile, a different plant from the German chamomile this entry is about.", "no_pre1900_source_found": false, "notes": ["The stored plant is German chamomile, Matricaria chamomilla. The old English herbals give their degrees for the garden or Roman chamomile, Chamaemelum nobile, which is a different plant."], "part_used": "Flower", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. A second-hand report: the text credits another writer.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Camomile, saith Galen, is hot and dry in the first degree, and is of thin parts", "gloss": "Gerard reports Galen: chamomile is hot and dry in the first degree.", "locator": "Book II, Chap. 262 'Of Camomile', The Temperature", "not_counted_why": "A second-hand report: the text credits another writer.", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. The heading covers garden and wild chamomile, but the degree is stated for the GARDEN (Roman) kind, a different species from the stored German chamomile. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Chamæmelum, sativum, sylvestre. Garden and Wild Chamomel. Garden Chamomel, is hot and dry in the first degree, and as gallant a medicine against the stone in the bladder as grows upon the earth", "gloss": "Garden chamomile is hot and dry in the first degree.", "locator": "Catalogue of simples, Herbs, 'Chamæmelum' (Gutenberg #49513, offset ~858460)", "not_counted_why": "The heading covers garden and wild chamomile, but the degree is stated for the GARDEN (Roman) kind, a different species from the stored German chamomile. Shown, not counted.", "note": "The heading covers garden and wild chamomile, but the degree is stated for the GARDEN (Roman) kind, a different species from the stored German chamomile. Shown, not counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Salmon's four kinds are the garden, naked-flowered, double-flowered and Roman chamomiles, all the creeping Chamaemelum, and he sets the wild kinds aside; the degree number is also garbled in the scan. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "IX. The Quahties. They are all of them hot and dry in three : Aperitive, Anodyne, Digeltive", "gloss": "Salmon's four kinds of chamomile are all hot and dry (the degree is damaged in the scan).", "locator": "Chap. CVIII 'Of Camomil', The Qualities (OCR near offset 908000)", "not_counted_why": "Salmon's four kinds are the garden, naked-flowered, double-flowered and Roman chamomiles, all the creeping Chamaemelum, and he sets the wild kinds aside; the degree number is also garbled in the scan. Shown, not counted.", "note": "Salmon's four kinds are the garden, naked-flowered, double-flowered and Roman chamomiles, all the creeping Chamaemelum, and he sets the wild kinds aside; the degree number is also garbled in the scan. Shown, not counted.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

