unted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Dandelion is like in temperature to Succory, that is to say, wild Endive. It is cold, but it drieth more, and doth withal cleanse, and open by reason of the bitterness which it hath joined with it", "gloss": "Dandelion is like succory in temperature: cold, but drier than succory.", "locator": "Book II, Chap. 32 'Of Dandelion', The Temperature and Virtues", "not_counted_why": "", "note": "Given partly by cross-reference to succory, and partly in Gerard's own words ('It is cold, but it drieth more').", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Taraxacon. Dandelion … it is a kind of Succory, and thither I refer you.", "gloss": "Culpeper refers dandelion to succory; his succory entry reads 'Cichorium. Succory … They are cold and dry in the second degree, cleansing and opening'.", "locator": "Catalogue of simples, Herbs, 'Taraxacon' (offset ~896907), read with 'Cichorium' (offset ~859657)", "not_counted_why": "", "note": "The temperature is given by cross-reference to succory, which Culpeper calls cold and dry in the second degree.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cold", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The Qualities. Dandelion is cold and dry in the firſt Degree: Aperitive, Abſterſive, Diuretick and a little Aſtringent", "gloss": "Dandelion is cold and dry in the first degree.", "locator": "Chap. CCX 'Of Dandelion, or Piss-a-Bed Common', The Qualities (OCR near offset 1692900)", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

