-- H016 Fennel (5 sources, SOURCES DISAGREE)
insert into _energetics_batch3 values ('H016', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources disagree, shown on page)", "temperature": "stays Warm (clear modern value; old sources disagree, shown on page)"}, "batch": 3, "checked_no_reading": ["Gerard 1633 Book II Chap. 411 'Of Fennel': the chapter has no Temperature section", "Salmon, Botanologia (1710), Chap. CCLII 'Of Fennel Common': the Qualities are given 'According to G[alen]', a report, and the degree is damaged in the scan"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Moist", "source": "Rajanighantu (c. 15th c.)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Neutral", "source": "Bencao Gangmu (1596)"}, {"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}]}, "disagreement_text": "On temperature, the old sources disagree: Culpeper (1653) and Bhavaprakasha (16th c.) read it as warm; Bencao Gangmu (1596) reads it as neutral. The app keeps warm, the modern reading of what the herb does in the body; the old readings are shown here but do not change it. On moisture, the old sources disagree: Culpeper (1653) and Bhavaprakasha (16th c.) read it as dry; Rajanighantu (c. 15th c.) reads it as moist. The app keeps dry, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are the seed and the root, so readings for either are counted."], "part_used": "Seed, Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Fœniculi. Of Fennel. The root is hot and dry, some say in the third degree, opening; it provokes urine, and menses, strengthens the liver", "gloss": "Fennel root is hot and dry, some say in the third degree.", "locator": "Catalogue of simples, Roots, 'Fœniculi' (Gutenberg #49513, offset ~812579)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source neutral, app warm).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "子氣味辛平無毒{{SKnotes|思邈曰苦辛微寒濇權曰苦辛得酒良炒黄用}}主治諸瘻霍亂及蛇傷", "gloss": "Fennel seed: pungent, NEUTRAL, not toxic. (Sun Simiao calls it bitter, pungent and slightly cold.)", "locator": "卷二十六 菜之一, 蘹香 (茴香), 子 氣味", "not_counted_why": "", "note": "", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. The same reading as the Bencao Gangmu, so it counts once; and this entry glosses fennel with the name for dill, which is a different plant. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "卷十一菜部小茴香一名莳萝。理氣開胃。辛平。理氣開胃。亦治寒疝。", "gloss": "Small fennel: regulates qi and opens the appetite; pungent, neutral.", "locator": "卷十一 菜部, 小茴香", "not_counted_why": "The same reading as the Bencao Gangmu, so it counts once; and this entry glosses fennel with the name for dill, which is a different plant. Shown, not counted.", "note": "The same reading as the Bencao Gangmu, so it counts once; and this entry glosses fennel with the name for dill, which is a different plant. Shown, not counted.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "छत्रा शालेयशालीनो मिश्रेया मधुरा मिसिः । शतपुष्पा लघुस्तीक्ष्णा पित्तकृद्दीपनी कटुः । उष्णा ज्वरानिलश्लेष्मव्रणशूलाक्षिरोगहृत् । मिश्रेया तद्गुणा प्रोक्ता विशेषाद्योनिशूलनुत् । … रूक्षोष्णा पाचनी", "gloss": "śatapuṣpā (dill) is light, sharp, pungent and HOT; miśreyā (fennel) is said to have the same qualities, and is DRY and HOT, digestive.", "locator": "Harītakyādi varga 2.89-92", "not_counted_why": "", "note": "Fennel's reading is given by cross-reference to dill in the same verse pair, and the following line (rūkṣoṣṇā) continues it.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: differs from the app moisture (source moist, app dry).", "assigns_moisture": "Moist", "assigns_temperature": null, "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": false, "excerpt": "miśreyā madhurā snigdhā kaṭuḥ kaphaharā parā / vātapittotthadoṣaghnī plīhajantuvināśanī", "gloss": "Fennel is sweet, SNIGDHA (unctuous, moist), pungent, the best remover of phlegm; it destroys disorders of wind and bile.", "locator": "Rājanighaṇṭu 6.16", "not_counted_why": "", "note": "Gives moisture only, no temperature.", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

