insert into _energetics_batch3 values ('H018', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Hot"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources disagree, shown on page)", "temperature": "stays Hot (clear modern value; old sources agree)"}, "batch": 3, "checked_no_reading": ["Culpeper's herbal chapter 'Garlick': 'Mars owns this herb', no degree", "Bencao Gangmu 卷二十六, 蒜 (小蒜) is the small garlic, Allium scorodoprasum, a different species"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}, {"reading": "Moist", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Moist", "source": "Rajanighantu (c. 15th c.)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}, {"reading": "Warm", "source": "Bencao Gangmu (1596)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}, {"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Warm", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "On moisture, the old sources disagree: Culpeper (1653) and Salmon (1710) read it as dry; Bhavaprakasha (16th c.) and Rajanighantu (c. 15th c.) read it as moist. The app keeps dry, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": [], "part_used": "Bulb", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Hot), so it stays Hot. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. A second-hand report: the text credits another writer.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Garlic is very sharp, hot, and dry, as Galen saith, in the fourth degree, and exulcerateth the skin by raising blisters.", "gloss": "Gerard reports Galen: garlic is hot and dry in the fourth degree.", "locator": "Book II, Chap. 97 'Of Garlic', The Temperature", "not_counted_why": "A second-hand report: the text credits another writer.", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Allium. Garlick. Hot and dry in the fourth degree, troublesome to the stomach; it dulls the sight, spoils a clear skin, resists poison", "gloss": "Garlic is hot and dry in the fourth degree.", "locator": "Catalogue of simples, Herbs, 'Allium' (Gutenberg #49513, offset ~841520; the same reading appears in the Roots catalogue at ~797462)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. The Qualities. It is hot and dry in the fourth Degree: Aperitive, Abſterſive, Attractive, Carminative, Digeſtive, Diſcuſſive, Anodyn, and Suppurative.", "gloss": "Garlic is hot and dry in the fourth degree.", "locator": "Chap. CCCVII 'Of Garlick', The Qualities (OCR near offset 2303108)", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "氣味辛温有毒乆食損人目", "gloss": "Garlic (hu, da suan): pungent, WARM, toxic; long eating harms the eyes.", "locator": "卷二十六 菜之一, 葫 (大蒜), 氣味", "not_counted_why": "", "note": "", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Hot", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "卷十一菜部大蒜即葫。宣、通竅辟惡。辛熱有毒。開胃健脾。消穀化食。", "gloss": "Garlic, that is hu: opens the orifices and drives off foulness; pungent, HOT, toxic; opens the appetite and strengthens the spleen.", "locator": "卷十一 菜部, 大蒜", "not_counted_why": "", "note": "", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Counted: agrees with the app temperature (warm); differs from the app moisture (source moist, app dry).", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "रसोनो वृंहणो वृष्यः स्निग्धोष्णः पाचनः सरः । रसे पाके च कटुकस्तीक्ष्णो मधुरको मतः ॥", "gloss": "rasono bṛṃhaṇo vṛṣyaḥ SNIGDHA-UṢṆAḤ pācanaḥ saraḥ: garlic is nourishing, aphrodisiac, UNCTUOUS and HOT, digestive and mobile.", "locator": "Harītakyādi varga 2.221", "not_counted_why": "", "note": "", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: agrees with the app temperature (warm); differs from the app moisture (source moist, app dry).", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "rasona uṣṇaḥ kaṭupicchilaś ca snigdho guruḥ svāduraso 'tibalyaḥ", "gloss": "Garlic is HOT, pungent, slimy, UNCTUOUS, heavy, sweet in taste and very strengthening.", "locator": "Rājanighaṇṭu 7.51", "not_counted_why": "", "note": "", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}], "sources_agree": false, "stored_before": {"moistur