-- H019 Ginger (6 sources, SOURCES DISAGREE)
insert into _energetics_batch3 values ('H019', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Hot"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources disagree, shown on page)", "temperature": "stays Hot (clear modern value; old sources agree)"}, "batch": 3, "checked_no_reading": ["Gerard 1633 Book II Chap. 44 'Of Ginger': the chapter has no Temperature section", "Salmon, Botanologia (1710): no ginger chapter (English herbs only)"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Moist", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Moist", "source": "Rajanighantu (c. 15th c.)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Bencao Gangmu (1596)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}, {"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Warm", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "On moisture, the old sources disagree: Culpeper (1653) reads it as dry; Bhavaprakasha (16th c.) and Rajanighantu (c. 15th c.) read it as moist. The app keeps dry, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the rhizome without distinguishing fresh from dried, so readings for either are counted; where a text gives both, only one is counted, and the other is shown."], "part_used": "Rhizome", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Hot), so it stays Hot. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Zingiberis. Of Ginger. Helps digestion, warms the stomach, clears the sight … it is hot and dry in the second degree.", "gloss": "Ginger is hot and dry in the second degree.", "locator": "Catalogue of simples, Roots, 'Zingiberis' (Gutenberg #49513, offset ~830450)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "氣味辛微温無毒}}{{SKnotes|藏器曰生薑温要熱則去皮要冷則留皮}}主治久服去臭氣通神明{{SKnotes|本經}}", "gloss": "Fresh ginger: pungent, slightly WARM, not toxic.", "locator": "卷二十六 菜之一, 生薑, 氣味", "not_counted_why": "", "note": "", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "卷十一菜部生薑宣、散寒發表、開痰止呕。辛溫。行陽分而祛寒發表。", "gloss": "Fresh ginger: disperses cold and releases the exterior, opens phlegm and stops vomiting; pungent, WARM.", "locator": "卷十一 菜部, 生薑 (the dried ginger entry at 卷十一 菜部, 乾薑 reads 辛熱, pungent and hot)", "not_counted_why": "", "note": "", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Counted: agrees with the app temperature (warm); differs from the app moisture (source moist, app dry).", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "शुण्ठी रुच्यामवातघ्नी पाचनी कटुका लघुः । स्निग्धोष्णा मधुरा पाके कफवातविबन्धनुत् ॥", "gloss": "śuṇṭhī … kaṭukā laghuḥ SNIGDHOṢṆĀ madhurā pāke: dried ginger is appetising, pungent, light, UNCTUOUS and HOT, sweet in post-digestion.", "locator": "Harītakyādi varga 2.45", "not_counted_why": "", "note": "", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Shown for context. The same text, on the fresh root; its dried-root verse is already counted above, so this is shown only. It is worth seeing, because one book calls the dried root unctuous and the fresh root dry.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "आर्द्रिका भेदिनी गुर्वीतीक्ष्णोष्णा दीपनी मता । कटुका मधुरा पाके रूक्षा वातकफापहा ॥", "gloss": "ārdrikā … TĪKṢṆOṢṆĀ … RŪKṢĀ: fresh ginger is purging, heavy, sharp and HOT, kindling, and DRY.", "locator": "Harītakyādi varga 2.49-50", "not_counted_why": "The same text, on the fresh root; its dried-root verse is already counted above, so this is shown only. It is worth seeing, because one book calls the dried root unctuous and the fresh root dry.", "note": "The same text, on the fresh root; its dried-root verse is already counted above, so this is shown only. It is worth seeing, because one book calls the dried root unctuous and the fresh root dry.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: agrees with the app temperature (warm); differs from the app moisture (source moist, app dry).", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "śuṇṭhī kaṭūṣṇā snigdhā ca kaphaśophānilāpahā / śūlabandhodarādhmānaśvāsaślīpadahāriṇī", "gloss": "Dried ginger is pungent, HOT and UNCTUOUS; it removes phlegm, swelling and wind.", "locator": "Rājanighaṇṭu 5.26 (his fresh-ginger verse 5.29 also reads kaṭūṣṇam ārdrakaṃ, pungent and hot)", "not_counted_why": "", "note": "", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Hot"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Hot"}}}$j$::jsonb);

