insert into _energetics_batch3 values ('H020', $j${"agreement_state": "none", "app_value": {"moisture": "Neutral", "temperature": "Neutral"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Neutral (clear modern value; no pre-1900 source found)"}, "batch": 3, "checked_no_reading": ["Bencao Congxin (1757), 卷十 果部 銀杏 一名白果: 'sweet, bitter, astringent and binding', a taste with no nature, and again the nut", "Porter Smith 1871: searched for Salisburia and Ginkgo, no article", "The ginkgo leaf has no pre-1900 medical entry in any of the texts opened"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this part. The one old reading describes the nut, and this entry is about the leaf.", "no_pre1900_source_found": false, "notes": ["The stored part is the LEAF. The old Chinese books use only the nut, and the leaf was not a medicine in China before the twentieth century."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Neutral), so it stays Neutral. Moisture: stored value clear (a definite Neutral), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. This is the nut, not the stored leaf. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味甘苦平濇無毒}}{{SKnotes|時珍曰熟食小苦微甘性温有小毒}}主治生食引疳解酒熟食益人", "gloss": "Ginkgo nut: sweet, bitter, NEUTRAL, astringent, not toxic. (Li Shizhen adds that cooked it is slightly bitter, a little sweet and warm in nature, with slight toxicity.)", "locator": "卷三十 果之二, 銀杏 (白果), 核仁 氣味", "not_counted_why": "This is the nut, not the stored leaf. Shown, not counted.", "note": "This is the nut, not the stored leaf. Shown, not counted.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Neutral", "temperature": "Neutral"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral"}, "temperature": {"status": "clear", "why": "a definite Neutral"}}}$j$::jsonb);

