-- H022 Ginseng (Asian) (3 sources, SOURCES DISAGREE)
insert into _energetics_batch3 values ('H022', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; old sources disagree, shown on page)"}, "batch": 3, "checked_no_reading": ["Porter Smith 1871, GINSENG: a long article on sorts, sources and trade, with no thermal quality"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Cool", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "On temperature, the old sources disagree: Shennong Bencao Jing (c. 200 CE) reads it as cold; Bencao Congxin (1757) reads it as warm. The app keeps warm, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": [], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source cool, app warm).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "==人參==味甘，微寒。主補五臟，安精神，定魂魄，止驚悸，除邪氣，明目、開心、益智。久服，輕身、延年。", "gloss": "Ginseng: sweet, slightly COLD. Supplements the five viscera, quiets the spirit, settles the hun and po, stops fright and palpitation, expels evil qi, brightens the eyes, opens the heart and benefits the wits.", "locator": "上經, 人參", "not_counted_why": "", "note": "The entry adds that Wu Pu records disagreement among the old masters: Shennong sweet and slightly cold, Tonged and Leigong bitter, Qibo and Huangdi sweet and not toxic.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. The heading repeats the Shennong reading, so it counts once, credited to Shennong. Li Shizhen's own discussion quotes his father: 'used raw its qi is cool, used cooked its qi is warm', which is a report of another writer.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "根氣味甘微寒無毒{{SKnotes|别録曰微温普曰神農小寒}}", "gloss": "Root: sweet, slightly cold, not toxic. (The Mingyi Bielu says slightly warm; Wu Pu says the Shennong has it slightly cold.)", "locator": "卷十二上 草之一, 人參, 根 氣味", "not_counted_why": "The heading repeats the Shennong reading, so it counts once, credited to Shennong. Li Shizhen's own discussion quotes his father: 'used raw its qi is cool, used cooked its qi is warm', which is a report of another writer.", "note": "The heading repeats the Shennong reading, so it counts once, credited to Shennong. Li Shizhen's own discussion quotes his father: 'used raw its qi is cool, used cooked its qi is warm', which is a report of another writer.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "卷一草部人參大補元氣，生陰血，亦瀉虚火。甘溫微苦。大補肺中元氣。", "gloss": "Ginseng greatly supplements the original qi, engenders yin blood, and drains vacuity fire; sweet, WARM, slightly bitter.", "locator": "卷一 草部 山草類, 人參", "not_counted_why": "", "note": "", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

