insert into _energetics_batch3 values ('H025', $j${"agreement_state": "agree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; old sources agree)"}, "batch": 3, "checked_no_reading": ["Dutt, Materia Medica of the Hindus (1877): Hydrocotyle asiatica (maṇḍūkaparṇī) appears only as an ingredient in mercurial pill formulas, with no thermal quality", "Dymock, Pharmacographia Indica Vols. I and III: searched for Hydrocotyle, no article found in the volumes opened", "Porter Smith 1871: no Hydrocotyle article"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Cool", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Cool", "source": "Bhavaprakasha (16th c.)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": [], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "==積雪草==味苦，寒。主大熱，惡創，癰疽，浸淫赤，皮膚赤，身熱。生川谷。", "gloss": "Ji xue cao: bitter, COLD. For great heat, malign sores, abscesses, spreading red eruptions, red skin and fever.", "locator": "中經, 積雪草", "not_counted_why": "", "note": "The entry's own gloss, 'the people of Jing and Chu call it the coin plant because its leaves are like coins', is the identification with the penny-leaved gotu kola.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. Repeats the Shennong reading word for word and credits it, so it counts once, credited to Shennong. Su Song's 'sweet and neutral' is a reported minority view.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味苦寒無毒{{SKnotes|大明曰苦辛頌曰甘平無毒}}主治大熱惡瘡癰疽浸滛赤熛皮膚赤身熱{{SKnotes|本經}}", "gloss": "Bitter, cold, not toxic. (Da Ming says bitter and pungent; Su Song says sweet and neutral.)", "locator": "卷十四 草之三, 積雪草, 氣味", "not_counted_why": "Repeats the Shennong reading word for word and credits it, so it counts once, credited to Shennong. Su Song's 'sweet and neutral' is a reported minority view.", "note": "Repeats the Shennong reading word for word and credits it, so it counts once, credited to Shennong. Su Song's 'sweet and neutral' is a reported minority view.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "ब्राह्मी कपोतवङ्का च सोमवल्ली सरस्वती । मण्डूकपर्णी माण्डूकी … ब्राह्मी हिमा सरा तिक्ता लघुर्मध्या च शीतला … तद्वन्मण्डूकपर्णिनी ॥", "gloss": "brāhmī himā sarā tiktā laghur … śītalā … tadvan maṇḍūkaparṇinī: brahmi is COLD, mobile, bitter, light and COOLING, and maṇḍūkaparṇī (gotu kola) is the same.", "locator": "Guḍūcyādi varga 4.279-281", "not_counted_why": "", "note": "The reading is given by cross-reference: the verse states the qualities of brahmi and then says gotu kola is likewise.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Shown for context. In the Rajanighantu maṇḍūkaparṇī appears as one name of ādityabhaktā, the sun plant, which is not clearly gotu kola. Identity too uncertain to count. The same name also appears at 2.188 in the Bhavaprakasha as a synonym of manjistha, madder, so this name is shared by more than one plant.", "assigns_moisture": null, "assigns_temperature": "Cool", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "ādityabhaktā varadārkabhaktā suvarcalā sūryalatārkakāntā / maṇḍūkaparṇī … ādityabhaktā śiśirā satiktā kaṭus tathogrā kaphahāriṇī ca", "gloss": "In this synonym group, which includes maṇḍūkaparṇī, the plant is called śiśirā (cool), bitter, pungent and sharp, removing phlegm.", "locator": "Rājanighaṇṭu 6.178-180", "not_counted_why": "In the Rajanighantu maṇḍūkaparṇī appears as one name of ādityabhaktā, the sun plant, which is not clearly gotu kola. Identity too uncertain to count. The same name also appears at 2.188 in the Bhavaprakasha as a synonym of manjistha, madder, so this name is shared by more than one plant.", "note": "In the Rajanighantu maṇḍūkaparṇī appears as one name of ādityabhaktā, the sun plant, which is not clearly gotu kola. Identity too uncertain to count. The same name also appears at 2.188 in the Bhavaprakasha as a synonym of manjistha, madder, so this name is shared by more than one plant.", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}], "sources_agree": true, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

do $do$
declare
  rec record;
  n int;
  written int := 0;
  skipped int := 0;
begin
  for rec in select herb_id, citation from _energetics_batch3 order by herb_id loop
    update public.herbs h
       set energetics_citation = rec.citation,
           last_updated = now()
     where h.herb_id = rec.herb_id
       and h.energetics_citation is distinct from rec.citation
       and (h.energetics_citation is null or h.energetics_citation ? 'batch');
    get diagnostics n = row_count;
    if n = 1 then
      written := written + 1;
    else
      if exists (select 1 from public.herbs
                  where herb_id = rec.herb_id and energetics_citation = rec.citation) then
        skipped := skipped + 1;
      else
        raise exception '%.energetics_citation: live value is neither NULL nor a batch object (or the herb is missing); not overwritten', rec.herb_id;
      end if;
    end if;
  end loop;
  raise notice 'energetics sources batch 3: % written, % already current', written, skipped;
end
$do$;

-- -----------------------------------------------------------------------------
-- 2. The same honesty fix, applied to the three herbs already live from batches 1
--    and 2 that have sources shown but none counted. Before this they rendered
--    nothing at all to a free reader, which reads as 'nobody looked'.
-- -----------------------------------------------------------------------------

do $do$
declare n int;
begin
  update public.herbs
     set energetics_citation = jsonb_set(energetics_citation,
           '{no_counted_source_line}', to_jsonb('No pre-1900 source found for this exact plant and part. The old books either speak of willows as a group, describe the leaves rather than the bark, or describe the weeping willow.'::text), true),
         last_updated = now()
   where herb_id = 'H164'
     and energetics_citation ? 'batch'
     -- only where the research really did count nothing; never invent the case
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(energetics_citation->'sources') s
                      where (s->>'counted')::boolean)
     and coalesce(energetics_citation->>'no_counted_source_line', '') is distinct from
         'No pre-1900 source found for this exact plant and part. The old books either speak of willows as a group, describe the leaves rather than the bark, or describe the weeping willow.';
  get diagnostics n = row_count;
  if n <> 1 then
    if exists (select 1 from public.herbs where herb_id = 'H164'
                and energetics_citation->>'no_counted_source_line' = 'No pre-1900 source found for this exact plant and part. The old books either speak of willows as a group, describe the leaves rather than the bark, or describe the weeping willow.') then
      raise notice 'H164 already carries its no-counted-source line, skipped';
    else
      raise exception 'H164: expected one batch herb with sources but none counted; not updated';
    end if;
  end if;
end
$do$;

