         'No pre-1900 source found for this reading. Both old texts pass on another writer''s account rather than giving their own.';
  get diagnostics n = row_count;
  if n <> 1 then
    if exists (select 1 from public.herbs where herb_id = 'H286'
                and energetics_citation->>'no_counted_source_line' = 'No pre-1900 source found for this reading. Both old texts pass on another writer''s account rather than giving their own.') then
      raise notice 'H286 already carries its no-counted-source line, skipped';
