-- -----------------------------------------------------------------------------
-- 3. The view gains the new line as a FREE field, appended after the existing
--    columns (CREATE OR REPLACE VIEW only allows adding at the end). Everything
--    above it is byte-identical to 20260916190000, including the Root gate.
-- -----------------------------------------------------------------------------
create or replace view public.herb_energetics_evidence_v as
select
  h.herb_id,
  (h.energetics_citation->>'batch')::int as batch,
  coalesce((h.energetics_citation->>'no_pre1900_source_found')::boolean, false)
    as no_pre1900_source_found,
  coalesce((h.energetics_citation->>'sources_agree')::boolean, false) as sources_agree,
  h.energetics_citation->>'agreement_state' as agreement_state,
  nullif(h.energetics_citation->>'disagreement_text', '') as disagreement_text,
  h.energetics_citation->>'rule' as rule,
  jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb))
    as source_count,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->'sources' else null::jsonb end as sources,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->'checked_no_reading' else null::jsonb end
    as checked_no_reading,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->'counted_readings' else null::jsonb end
    as counted_readings,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->>'rule_general' else null::text end as rule_general,
  nullif(h.energetics_citation->>'no_counted_source_line', '')
    as no_counted_source_line
  from public.herbs h
 where h.energetics_citation ? 'batch'
   and coalesce(h.status, '') not like 'Hidden%';

-- -----------------------------------------------------------------------------
-- 4. Verification. Any failure aborts the whole transaction.
-- -----------------------------------------------------------------------------
do $do$
declare
  bad text[] := '{}';
  n int;
  moved text;
begin
  -- 2a. Batch 3 landed, and the earlier batches are still there.
  select count(*) into n from public.herbs where (energetics_citation->>'batch')::int = 3;
  if n <> 25 then bad := bad || ('batch 3 herbs: ' || n || ', expected 25'); end if;
  select count(*) into n from public.herbs where energetics_citation ? 'batch';
  if n <> 75 then bad := bad || ('batch citations in total: ' || n || ', expected 75'); end if;
  select count(*) into n from public.herbs
   where energetics_citation is not null and not (energetics_citation ? 'batch');
  if n <> 69 then bad := bad || ('legacy single-source citations: ' || n || ', expected 69'); end if;

  -- 2b. Every batch herb has a sources array or the honest no-source flag, and
  --     every source carries the fields the page renders.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (jsonb_typeof(energetics_citation->'sources') = 'array'
          or (energetics_citation->>'no_pre1900_source_found')::boolean);
  if n <> 75 then bad := bad || ('batch herbs with a sources array or the no-source flag: ' || n || ', expected 75'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0
     and not (energetics_citation->>'no_pre1900_source_found')::boolean;
  if n <> 0 then bad := bad || (n || ' herb(s) have no source and no no-source flag'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch' and coalesce(energetics_citation->>'rule', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) carry no basis line'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch';
  if n <> 189 then bad := bad || ('stored sources: ' || n || ', expected 189'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s ? 'source' and s ? 'year' and s ? 'corpus' and s ? 'tier'
              and s ? 'assigns_temperature' and s ? 'assigns_moisture'
              and s ? 'excerpt' and s ? 'locator' and s ? 'url'
              and s ? 'agreement' and s ? 'counted');
  if n <> 0 then bad := bad || (n || ' source(s) are missing a required field'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s->>'counted')::boolean
     and coalesce(s->>'not_counted_why', '') = '';
  if n <> 0 then bad := bad || (n || ' uncounted source(s) do not say why they were not counted'); end if;

  -- 2c. Never claim agreement the data does not carry.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'agreement_state' = 'disagree'
     and coalesce(energetics_citation->>'disagreement_text', '') = '';
  if n <> 0 then bad := bad || (n || ' disagreeing herb(s) carry no disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and coalesce(energetics_citation->>'disagreement_text', '') <> '';
  if n <> 0 then bad := bad || (n || ' agreeing herb(s) also carry a disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0;
  if n <> 0 then bad := bad || (n || ' herb(s) claim agreement with no sources at all'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'disagreement_text' like '%' || chr(8212) || '%';
  if n <> 0 then bad := bad || (n || ' disagreement sentence(s) contain an em dash'); end if;

  -- 2c-bis. Every batch herb that found sources but counted none of them must
  --         carry its own plain sentence saying why. Silence there would read as
  --         'nobody looked'. Exactly 7 herbs are in that position.
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean);
  if n <> 7 then bad := bad || ('herbs with sources but none counted: ' || n || ', expected 7'); end if;
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean)
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) counted no source and say nothing about why'); end if;
  -- and the line is never attached to a herb that DID count a source, which would
  -- contradict the evidence shown right beside it.
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') <> ''
     and exists (select 1 from jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
                  where (s->>'counted')::boolean);
  if n <> 0 then bad := bad || (n || ' herb(s) claim no counted source while showing one'); end if;

  -- 2d. Batch 3 changes NO app value. Nothing may have moved.
  select count(*), string_agg(h.herb_id, ', ' order by h.herb_id) into n, moved
    from public.herbs h join _energetics_before_b3 b using (herb_id)
   where h.temperature is distinct from b.temperature
      or h.moisture is distinct from b.moisture;
  if n <> 0 then
    bad := bad || ('energetics moved on ' || n || ' herb(s): ' || coalesce(moved, 'none') || '; batch 3 must move none');
  end if;
  select count(*) into n from public.herbs;
  if n <> (select count(*) from _energetics_before_b3) then
    bad := bad || 'the herb count changed'::text;
  end if;

  -- 2e. The existing view now carries every batch herb.
  select count(*) into n from public.herb_energetics_evidence_v;
  if n <> 75 then bad := bad || ('herb_energetics_evidence_v rows: ' || n || ', expected 75'); end if;

  if array_length(bad, 1) is not null then
    raise exception 'energetics sources batch 3: checks failed: %', array_to_string(bad, '; ');
  end if;
end
$do$;

-- 2f. The tier gate, proved by READING the view as the anon role on a batch 3
--     herb rather than by reading the view definition. A blind check that returns
--     nothing looks healthy, so this asserts a NON-EMPTY free result and a NULL
--     source list together.
do $do$
declare
  bad text[] := '{}';
  free_text text;
  free_flag boolean;
  src jsonb;
  seen int;
begin
  begin
    set local role anon;
  exception when insufficient_privilege then
    raise notice 'cannot SET ROLE anon here; the functional tier check was skipped';
    return;
  end;
  select count(*) into seen from public.herb_energetics_evidence_v;
  if seen <> 75 then bad := bad || ('anon sees ' || seen || ' evidence rows, expected 75'); end if;
  select disagreement_text, sources into free_text, src
    from public.herb_energetics_evidence_v where herb_id = 'H003';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the disagreement sentence on H003'::text;
  end if;
  if src is not null then
    bad := bad || 'anon can read the Root source list on H003'::text;
  end if;
  select no_pre1900_source_found into free_flag
    from public.herb_energetics_evidence_v where herb_id = 'H005';
  if free_flag is not true then
    bad := bad || 'anon cannot read the no-source flag on H005'::text;
  end if;
  -- The new line is FREE, like the disagreement sentence: honesty is not a paid
  -- feature. Checked on a herb that has it, and on one that must not.
  select no_counted_source_line, sources into free_text, src
    from public.herb_energetics_evidence_v where herb_id = 'H299';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the no-counted-source line on H299'::text;
  end if;
  if src is not null then
    bad := bad || 'anon can read the Root source list on H299'::text;
  end if;
  select no_counted_source_line into free_text
    from public.herb_energetics_evidence_v where herb_id = 'H003';
  if free_text is not null then
    bad := bad || 'a herb with counted sources (H003) carries a no-counted-source line'::text;
  end if;
  reset role;
  if array_length(bad, 1) is not null then
    raise exception 'energetics sources batch 3: tier gate failed: %', array_to_string(bad, '; ');
  end if;
end
$do$;

commit;
